// Filtra e assegna un punteggio ai lead esportati da Outscraper.
// Criteri del business: attivita' avviata (rating alto, recensioni vere)
// ma con presenza digitale debole (niente sito o sito scadente).
const get = (row, keys) => {
  for (const k of keys) {
    if (row[k] !== undefined && row[k] !== null && String(row[k]).trim() !== '') {
      return String(row[k]).trim();
    }
  }
  return '';
};

const out = [];
for (const item of items) {
  const r = item.json;
  const name = get(r, ['name', 'nome', 'business_name', 'title']);
  const rating = parseFloat(get(r, ['rating', 'stars', 'valutazione']).replace(',', '.')) || 0;
  const reviews = parseInt(get(r, ['reviews', 'reviews_count', 'recensioni', 'reviews_link_count']), 10) || 0;
  const site = get(r, ['site', 'website', 'sito']);
  const phone = get(r, ['phone', 'telefono', 'phone_number']);
  const email = get(r, ['email_1', 'email', 'email_2']);
  const address = get(r, ['full_address', 'address', 'indirizzo']);
  const category = get(r, ['type', 'category', 'categoria', 'subtypes']);
  const city = get(r, ['city', 'citta', 'comune']);

  if (!name) continue;
  // Requisiti minimi: business reale con reputazione, non una attivita' morta
  if (rating < 4.0 || reviews < 20) continue;

  let score = 0;
  const reasons = [];
  if (!site) {
    score += 40;
    reasons.push('nessun sito web');
  } else if (/facebook\.|instagram\.|wixsite|jimdo|sites\.google|linktr\.ee|business\.site/i.test(site)) {
    score += 30;
    reasons.push('sito debole (pagina social o builder gratuito)');
  }
  if (rating >= 4.0 && rating <= 4.4) {
    score += 15;
    reasons.push('rating migliorabile (' + rating + ')');
  }
  if (reviews >= 20 && reviews < 80) {
    score += 10;
    reasons.push('poche recensioni rispetto ai competitor');
  }
  if (email) score += 20; // contattabile via email
  if (phone) score += 5;

  // Sotto 30 punti il lead non vale l'outreach
  if (score < 30) continue;

  out.push({
    json: {
      name,
      category,
      city,
      address,
      phone,
      email,
      site,
      rating,
      reviews,
      score,
      reasons: reasons.join('; '),
      status: 'qualificato',
      created_at: new Date().toISOString().slice(0, 10),
    },
  });
}

out.sort((a, b) => b.json.score - a.json.score);
return out;
